"""Tests for tools/strip_claude_footer.py."""

import numpy as np
import pytest

from tools.strip_claude_footer import Post, event_post, strip_footer

# The two forms that the GitHub proxy writes: with and without a session link.
FOOTERS = (
    "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_",
    "\n\n---\n_Generated by [Claude Code](https://claude.ai/code/session_01K7L44suQVjzjEqbYozFCrS)_",
)

BODIES = (
    "Fixes the parser.",
    "## Summary\n\n- one\n- two\n\n```python\nx = 1\n```",
    "A table:\n\n| a | b |\n|---|---|\n| 1 | 2 |",
    "Ends with a rule\n\n---",
    "",
)


def _random_body(rng: np.random.Generator) -> str:
    """Text from words, newlines, rules and markdown, without the footer."""
    parts = ["word", "\n", "\n\n", "---", "_x_", "[link](https://example.com)", " "]
    return "".join(rng.choice(parts, int(rng.integers(0, 30)))).rstrip()


@pytest.mark.parametrize("footer", FOOTERS)
def test_strip_removes_only_the_footer(footer):
    rng = np.random.default_rng(0)
    bodies = [*BODIES, *(_random_body(rng) for _ in range(200))]
    for body in bodies:
        assert strip_footer(body + footer) == body.rstrip()
        assert strip_footer(body + footer + "\n") == body.rstrip()


def test_strip_leaves_a_body_without_the_footer_unchanged():
    rng = np.random.default_rng(1)
    for body in [*BODIES, *(_random_body(rng) for _ in range(200))]:
        assert strip_footer(body) == body


@pytest.mark.parametrize("footer", FOOTERS)
def test_strip_is_idempotent_and_ignores_a_footer_inside_the_text(footer):
    once = strip_footer("Body" + footer)
    assert strip_footer(once) == once
    quoted = "Body" + footer + "\n\nMore text after it."
    assert strip_footer(quoted) == quoted


def test_strip_keeps_a_similar_line_from_another_tool():
    body = "Body\n\n---\n_Generated by [Other Tool](https://example.com)_"
    assert strip_footer(body) == body


def test_event_post_finds_the_post_of_each_event():
    api = "https://api.github.com/repos/o/r"
    comment = {"comment": {"url": f"{api}/issues/comments/1", "body": "c"}}
    issue = {"issue": {"url": f"{api}/issues/2", "body": None}}
    pull = {"pull_request": {"url": f"{api}/pulls/3", "body": "p"}}
    review = {"review": {"id": 4, "body": "r"}, **pull}
    assert event_post("issue_comment", comment) == Post(
        comment["comment"]["url"], "PATCH", "c"
    )
    assert event_post("pull_request_review_comment", comment) == Post(
        comment["comment"]["url"], "PATCH", "c"
    )
    assert event_post("issues", issue) == Post(f"{api}/issues/2", "PATCH", "")
    assert event_post("pull_request_target", pull) == Post(
        f"{api}/pulls/3", "PATCH", "p"
    )
    assert event_post("pull_request_review", review) == Post(
        f"{api}/pulls/3/reviews/4", "PUT", "r"
    )
    assert event_post("push", {}) is None
